-- Canonical standard library. IDs are explicit in exercise-library.tsv and must never be recycled.
-- Regenerate only by the catalog verifier; reordering the TSV must not change an ID.
begin;
create temporary table fyrup_catalog_seed(id uuid,name text,primary_muscle text,secondary_muscles text,equipment text,exercise_type text) on commit drop;
select id,name,primary_muscle,equipment,exercise_type,false,null,false from fyrup_catalog_seed;
select c.id,s.muscle from fyrup_catalog_seed c cross join lateral unnest(string_to_array(c.secondary_muscles,',')) s(muscle)
where s.muscle<>'';
commit;
